public class Main {
    public static int linearSearch(int[] arr, int target) {
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == target) {
                return i;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] numbers = {7, 4, 9, 2, 6};
        int target = 9;
        System.out.println(linearSearch(numbers, target));
    }
}
